-- Migration: author expected_concepts (Spanish) and feedback_profile
-- (3-band WSET3-grounded distinction feedback) for or_bank items OR_032-OR_106.
--
-- Context: evaluate-or (Edge Function) reads or_bank.feedback_profile to
-- surface a per-question, WSET3-grounded explanation of why a student's
-- response landed at its depth band (STRONG_RESPONSE / DEVELOPING_RESPONSE /
-- FOUNDATIONAL_RESPONSE). This migration backfills that content for the 75
-- items that previously had it missing or in English, so every item in the
-- bank now supports the distinction-level feedback loop.
--
-- This migration reproduces content that was already applied directly to
-- production via the Supabase MCP execute_sql tool (batched, item_id-range
-- by item_id-range) during the same work session. It exists so the schema
-- change is version-controlled and reproducible from a clean database, not
-- only live in the hosted project.

begin;

update public.or_bank set expected_concepts = '["evolución del color hacia tonos más dorados","desarrollo de aromas secundarios y terciarios","notas de vainilla y tostado del roble","aumento de la sensación de textura y volumen en boca","prolongación del final de boca"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: describe la evolución sensorial en varias dimensiones (color, aroma, textura, final de boca) y conecta el envejecimiento con el desarrollo de complejidad, no solo con el sabor a roble.","DEVELOPING_RESPONSE":"Buena base. Mencionas algunos cambios sensoriales, pero profundiza cubriendo también la evolución del color y la prolongación del final de boca para dar una descripción más completa.","FOUNDATIONAL_RESPONSE":"Identificas que el roble aporta aromas, pero una respuesta completa debe describir el conjunto de cambios sensoriales: color, aroma, textura y final de boca, no solo mencionar el sabor a madera."}'::jsonb where item_id = 'OR_032';
update public.or_bank set expected_concepts = '["temperaturas más bajas a mayor altitud","maduración más lenta de la uva","mayor retención de ácido málico","menor acumulación de azúcar","perfil final más fresco"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: explica la cadena causal completa altitud → temperatura → velocidad de maduración → retención de acidez y azúcar, y conecta esto con el perfil sensorial final del vino.","DEVELOPING_RESPONSE":"Buen fundamento. Conectas la altitud con la temperatura, pero profundiza explicando cómo esto afecta específicamente la retención de ácido málico y la acumulación de azúcar.","FOUNDATIONAL_RESPONSE":"Mencionas que la altitud influye en la madurez, pero necesitas explicar el mecanismo: menor temperatura → maduración más lenta → mayor acidez y menor azúcar → perfil más fresco."}'::jsonb where item_id = 'OR_033';
update public.or_bank set expected_concepts = '["clima frío: predominio de aromas primarios","clima frío: acidez más alta","clima cálido: mayor presencia de aromas secundarios y terciarios","clima cálido: acidez más baja","diferencial de madurez entre ambos climas"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: contrasta ambos climas en aroma y en estructura (acidez), explicando el diferencial de madurez que causa estas diferencias, no solo enumerando características por separado.","DEVELOPING_RESPONSE":"Buen contraste. Mencionas diferencias de acidez o aroma, pero asegúrate de cubrir ambas dimensiones para ambos climas y de explicar el porqué del diferencial de madurez.","FOUNDATIONAL_RESPONSE":"Describes un clima pero no contrastas explícitamente ambos. Una comparación completa necesita mostrar cómo cada clima afecta tanto el perfil aromático como la acidez."}'::jsonb where item_id = 'OR_034';
update public.or_bank set expected_concepts = '["preservación de aromas primarios","acidez marcada y definida","estructura de carácter mineral","juicio de calidad dependiente del estilo esperado","expresión clara de la variedad"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: emites un juicio de calidad respaldado por evidencia específica (fruta, acidez, mineralidad) y lo contextualizas según el estilo esperado para este tipo de vino.","DEVELOPING_RESPONSE":"Buen juicio inicial. Mencionas evidencia específica de fruta o acidez, pero profundiza explicando por qué esa evidencia respalda tu valoración de calidad.","FOUNDATIONAL_RESPONSE":"Das un juicio de calidad sin suficiente evidencia. Una evaluación completa describe fruta, acidez y estructura mineral, y explica cómo eso se ajusta al estilo esperado del vino."}'::jsonb where item_id = 'OR_035';
update public.or_bank set expected_concepts = '["suavización de la textura","mayor complejidad aromática","pérdida de acidez","compromiso con la frescura","riesgo de diacetilo excesivo","valor dependiente del estilo buscado"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: pondera beneficios (textura, complejidad) y costes (pérdida de frescura, riesgo de diacetilo) y llega a una conclusión sobre cuándo la fermentación maloláctica es o no apropiada.","DEVELOPING_RESPONSE":"Buen análisis parcial. Mencionas un beneficio o un riesgo, pero una evaluación completa debe ponderar ambos lados y concluir en qué estilos conviene usarla.","FOUNDATIONAL_RESPONSE":"Mencionas la fermentación maloláctica pero no evalúas su impacto. Explica tanto lo que gana (textura, complejidad) como lo que pierde (acidez, frescura) el vino."}'::jsonb where item_id = 'OR_036';
update public.or_bank set expected_concepts = '["tipos de certificación (orgánica, biodinámica)","aumento del coste de producción","posibilidad de precio premium","percepción del consumidor","posicionamiento de mercado","mayor intensidad de mano de obra"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Análisis completo: presentas tanto el coste (mano de obra, rendimiento) como el beneficio (percepción, precio premium) de la certificación, y llegas a una conclusión razonada sobre su viabilidad.","DEVELOPING_RESPONSE":"Buen punto de partida. Mencionas costes o beneficios, pero para un análisis completo contrasta ambos lados y concluye sobre el balance entre ellos.","FOUNDATIONAL_RESPONSE":"Mencionas la sostenibilidad de forma general. Analiza específicamente cómo afecta al coste de producción y cómo eso se traduce en percepción del consumidor y precio."}'::jsonb where item_id = 'OR_037';
update public.or_bank set expected_concepts = '["control de temperatura durante la fermentación","fermentación en depósitos de acero inoxidable","evitar la fermentación maloláctica","uso mínimo o nulo de roble","embotellado temprano","preservación de la acidez"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Recomendación completa: das un enfoque específico (fermentación fría en acero, sin FML, embotellado temprano) y justificas cada elección en función de preservar la expresión de terroir.","DEVELOPING_RESPONSE":"Buena recomendación general. Mencionas técnicas específicas, pero explica por qué cada una preserva mejor la expresión de terroir del Riesling.","FOUNDATIONAL_RESPONSE":"Das una recomendación vaga. Sé específico: qué temperatura, qué tipo de depósito, y por qué evitar el roble y la fermentación maloláctica en este estilo."}'::jsonb where item_id = 'OR_038';
update public.or_bank set expected_concepts = '["clima continental","suelos ricos en piedra caliza","estación de cultivo fresca","rendimientos bajos","variedades Pinot Noir y Chardonnay","regulaciones regionales estrictas","expresión fiel del lugar de origen"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: identifica múltiples factores (clima, suelo, rendimiento, variedad, regulación) y explica cómo cada uno contribuye a la expresión de terroir característica de Borgoña.","DEVELOPING_RESPONSE":"Buena identificación de factores. Mencionas uno o dos, pero conecta explícitamente cada factor con el estilo final del vino para completar la explicación.","FOUNDATIONAL_RESPONSE":"Mencionas Borgoña como región de vinos finos, pero no identificas los factores específicos (clima, suelo, rendimiento) que explican por qué."}'::jsonb where item_id = 'OR_039';
update public.or_bank set expected_concepts = '["aclarado o apertura del color","suavización de los taninos","apertura de los aromas","mayor expresión de la fruta","cambio en la percepción del alcohol","mayor integración estructural"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: describe cambios en las tres dimensiones (color, aroma, estructura) y explica cómo la exposición al aire favorece la integración general del vino.","DEVELOPING_RESPONSE":"Buena descripción parcial. Mencionas cambios en una o dos dimensiones; añade las que falten (color, aroma o estructura) para una descripción completa.","FOUNDATIONAL_RESPONSE":"Mencionas que el vino cambia al airearse, pero describe específicamente qué ocurre con el color, el aroma y los taninos."}'::jsonb where item_id = 'OR_040';
update public.or_bank set expected_concepts = '["variación en el tamaño de las bayas","relación piel-pulpa","nivel de madurez alcanzado","diferencias de exposición solar","variación en el drenaje del suelo","microvariación del terroir dentro del viñedo"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: explica cómo varios factores de microterroir (drenaje, exposición) generan diferencias en tamaño de baya y relación piel-pulpa, lo cual causa la variación tánica.","DEVELOPING_RESPONSE":"Buen fundamento. Mencionas un factor de variación, pero conecta explícitamente cómo ese factor cambia la relación piel-pulpa o la madurez para causar la diferencia tánica.","FOUNDATIONAL_RESPONSE":"Mencionas que hay variación tánica pero no explicas su causa. Un viñedo no es uniforme: factores como el drenaje y la exposición solar varían y afectan la concentración de cada parcela."}'::jsonb where item_id = 'OR_041';
update public.or_bank set expected_concepts = '["viña vieja: raíces más profundas","viña vieja: menores rendimientos","viña vieja: mayor concentración","viña vieja: mayores niveles de tanino","beneficio estructural para la guarda","mayor desarrollo de complejidad con el tiempo"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Comparación completa: contrasta ambos tipos de viñedo en rendimiento, concentración y estructura tánica, y conecta esas diferencias con el potencial de guarda de cada vino.","DEVELOPING_RESPONSE":"Buen contraste inicial. Mencionas una diferencia (por ejemplo, rendimiento), pero conéctala explícitamente con el potencial de envejecimiento para completar la comparación.","FOUNDATIONAL_RESPONSE":"Mencionas que la edad de la viña importa, pero no explicas por qué: menor rendimiento y mayor concentración en viña vieja generan más estructura para la guarda."}'::jsonb where item_id = 'OR_042';
update public.or_bank set expected_concepts = '["los taninos como indicador de madurez","la volatilidad o difusión del aroma","estimación de la edad del vino","contraste entre estructura y desarrollo aromático","trayectoria de envejecimiento","juicio de calidad en contexto"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: usa tanto la estructura tánica como el estado del aroma como evidencia para estimar la edad, y emite un juicio de calidad que considera ambos en conjunto.","DEVELOPING_RESPONSE":"Buen juicio parcial. Usas un indicador (taninos o aroma), pero considera ambos en conjunto para estimar mejor la edad y la trayectoria de envejecimiento.","FOUNDATIONAL_RESPONSE":"Das un juicio sin suficiente evidencia. Explica qué indica la estructura tánica fuerte y qué indica el aroma difuso sobre la edad probable del vino."}'::jsonb where item_id = 'OR_043';
update public.or_bank set expected_concepts = '["permeabilidad al oxígeno","riesgo de contaminación por corcho (TCA)","beneficios de los cierres alternativos","consistencia en la evolución del vino","compromiso entre coste y fiabilidad"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: pondera la permeabilidad al oxígeno del corcho natural (beneficiosa para la guarda) frente al riesgo de TCA, comparándolo con la consistencia de los cierres alternativos.","DEVELOPING_RESPONSE":"Buen análisis parcial. Mencionas un riesgo o beneficio, pero una evaluación completa pondera ambos cierres considerando permeabilidad, riesgo de defecto y consistencia.","FOUNDATIONAL_RESPONSE":"Mencionas el corcho o las alternativas, pero no evalúas su impacto real en la evolución del vino a largo plazo."}'::jsonb where item_id = 'OR_044';
update public.or_bank set expected_concepts = '["origen de los taninos (piel, pepitas, madera)","taninos de pepita: mayor astringencia","taninos de piel: aportan estructura","control de la extracción durante la vinificación","gestión de la temperatura de maceración","beneficios de los taninos para la guarda","mecanismos de suavización con el tiempo"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Análisis completo: distingues los distintos orígenes del tanino, explicas cómo el enólogo controla su extracción, y conectas esto con el potencial de guarda y suavización con el tiempo.","DEVELOPING_RESPONSE":"Buen análisis parcial. Mencionas un origen o técnica de control, pero para un análisis completo cubre también cómo se suavizan los taninos con el envejecimiento.","FOUNDATIONAL_RESPONSE":"Mencionas que los taninos son importantes, pero no explicas su origen ni cómo el enólogo puede gestionarlos durante la vinificación."}'::jsonb where item_id = 'OR_045';
update public.or_bank set expected_concepts = '["papel de cada varietal en el ensamblaje","Cabernet Sauvignon aporta estructura","Merlot aporta cuerpo y carnosidad","Petit Verdot aporta potencial de guarda","equilibrio de las proporciones","evaluación sensorial iterativa del ensamblaje"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Recomendación completa: asignas un papel específico a cada varietal (estructura, cuerpo, guarda) y explicas cómo ajustar las proporciones mediante cata iterativa para lograr el equilibrio buscado.","DEVELOPING_RESPONSE":"Buena recomendación. Mencionas uno o dos varietales, pero explica el papel específico de cada uno en el ensamblaje final.","FOUNDATIONAL_RESPONSE":"Recomiendas un ensamblaje sin explicar qué aporta cada varietal. Especifica el papel de cada uva (estructura, fruta, cuerpo) en la mezcla."}'::jsonb where item_id = 'OR_046';
update public.or_bank set expected_concepts = '["suelo de valle: fruta más madura","ladera: mayor estructura y complejidad","variación de la influencia de la niebla","expresión mineral del suelo","diferencia de madurez del Cabernet Sauvignon","identidad regional distintiva"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: identifica factores de clima y suelo, y explica cómo cada uno genera diferencias sensoriales específicas entre ambas regiones.","DEVELOPING_RESPONSE":"Buena identificación parcial. Mencionas un factor (por ejemplo, la niebla), pero conéctalo explícitamente con el estilo resultante del vino.","FOUNDATIONAL_RESPONSE":"Mencionas que Napa y Sonoma son distintas, pero no identificas los factores de clima y suelo que explican la diferencia."}'::jsonb where item_id = 'OR_047';
update public.or_bank set expected_concepts = '["primera fermentación","segunda fermentación en botella","autólisis de las levaduras","contacto prolongado con las lías","textura cremosa resultante","desarrollo de complejidad aromática","formación de burbujas finas"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: describe el proceso completo (primera y segunda fermentación, autólisis) y conecta cada etapa con su efecto sensorial específico en el vino final.","DEVELOPING_RESPONSE":"Buena descripción parcial del proceso. Mencionas una o dos etapas; añade las que falten y conéctalas con el efecto en el sabor.","FOUNDATIONAL_RESPONSE":"Mencionas que hay una segunda fermentación, pero no describes el proceso completo ni cómo afecta al sabor final."}'::jsonb where item_id = 'OR_048';
update public.or_bank set expected_concepts = '["día cálido: acumulación de azúcar","noche fresca: retención de acidez","beneficio del rango de temperatura diurno: azúcar y acidez simultáneos","madurez de sabor equilibrada con la acidez","zonas con rango de temperatura diurno ideal","complejidad aromática por preservación de ácidos"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: explica cómo el calor diurno y el frío nocturno actúan de forma complementaria, logrando madurez de sabor sin sacrificar la acidez, y conecta esto con la complejidad aromática final.","DEVELOPING_RESPONSE":"Buen fundamento. Explicas una parte del mecanismo (día o noche), pero conecta ambos para mostrar por qué el rango de temperatura diurno beneficia tanto al azúcar como a la acidez.","FOUNDATIONAL_RESPONSE":"Mencionas el rango de temperatura diurno, pero no explicas el mecanismo: por qué el día cálido acumula azúcar y la noche fresca retiene acidez."}'::jsonb where item_id = 'OR_049';
update public.or_bank set expected_concepts = '["botrytis: complejidad de la podredumbre noble","botrytis: notas de miel y cítricos","botrytis: retención de acidez","deshidratación: concentración de azúcares","deshidratación: menor complejidad","diferencia en el potencial de guarda"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Comparación completa: contrasta ambos métodos en complejidad aromática, acidez y potencial de guarda, explicando por qué la podredumbre noble suele producir vinos más elegantes y longevos.","DEVELOPING_RESPONSE":"Buen contraste inicial. Mencionas una diferencia (por ejemplo, complejidad), pero cubre también la acidez y el potencial de guarda para completar la comparación.","FOUNDATIONAL_RESPONSE":"Mencionas ambos métodos pero no los comparas. Explica en qué se diferencian en complejidad, acidez y capacidad de envejecer."}'::jsonb where item_id = 'OR_050';
update public.or_bank set expected_concepts = '["papel del alcohol: estructura y conservación","nivel de dulzor apropiado","complejidad aromática","indicadores de crianza","expectativas según el estilo","juicio de equilibrio"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: valoras el papel del alcohol, el dulzor y la complejidad aromática en conjunto, y emites un juicio de calidad contextualizado según el estilo esperado del vino fortificado.","DEVELOPING_RESPONSE":"Buen juicio parcial. Mencionas uno de los tres elementos (alcohol, dulzor, aroma), pero considera los tres juntos para un juicio de equilibrio más completo.","FOUNDATIONAL_RESPONSE":"Das un juicio de calidad sin suficiente evidencia. Describe el papel del alcohol, el dulzor y la complejidad aromática antes de juzgar el equilibrio."}'::jsonb where item_id = 'OR_051';
update public.or_bank set expected_concepts = '["polimerización de taninos","estabilización del color","riesgo de oxidación","posibilidad de sobre-oxidación","consideración del coste","impacto impredecible en el estilo"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Evaluación completa: pondera los beneficios (polimerización, estabilidad de color) frente a los riesgos (sobre-oxidación, coste) y concluye sobre cuándo conviene usar la microoxigenación.","DEVELOPING_RESPONSE":"Buen análisis parcial. Mencionas un beneficio o riesgo, pero una evaluación completa debe ponderar ambos lados.","FOUNDATIONAL_RESPONSE":"Mencionas la microoxigenación pero no evalúas su impacto. Explica qué se gana (taninos más suaves) y qué se arriesga (oxidación excesiva)."}'::jsonb where item_id = 'OR_052';
update public.or_bank set expected_concepts = '["distinción entre pH y acidez total","estabilidad microbiológica","expresión del color según el pH","sensibilidad a la oxidación","impacto en la trayectoria de envejecimiento","herramientas del enólogo para gestionar el pH"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Análisis completo: distingues pH de acidez total, y explicas su influencia conjunta en estabilidad microbiológica, color y capacidad de envejecimiento, incluyendo cómo el enólogo puede gestionarlo.","DEVELOPING_RESPONSE":"Buen análisis parcial. Mencionas cómo el pH afecta uno de estos aspectos (color, estabilidad), pero cubre también los demás para un análisis más completo.","FOUNDATIONAL_RESPONSE":"Mencionas el pH pero no explicas cómo interactúa con la acidez, los taninos o el color del vino."}'::jsonb where item_id = 'OR_053';
update public.or_bank set expected_concepts = '["objetivo de menor grado alcohólico","mayor retención de acidez","madurez óptima para el aroma","precisión en el momento de cosecha","vendimias múltiples frente a una sola","objetivos analíticos: azúcar, pH, acidez total"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Recomendación completa: especificas objetivos analíticos concretos (azúcar, pH, acidez) y justificas el momento de cosecha en función de preservar la acidez necesaria para un espumoso elegante.","DEVELOPING_RESPONSE":"Buena recomendación general. Mencionas cosechar temprano, pero especifica los objetivos analíticos concretos que buscas.","FOUNDATIONAL_RESPONSE":"Das una recomendación vaga sobre el momento de cosecha sin especificar por qué ese momento es el adecuado para un espumoso de alta elegancia."}'::jsonb where item_id = 'OR_054';
update public.or_bank set expected_concepts = '["gestión del área foliar","equilibrio en la exposición del fruto","acumulación de azúcar","madurez fenólica","intercepción de luz solar","prevención del sombreado excesivo"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: identifica múltiples mecanismos del manejo del dosel (área foliar, exposición, luz) y explica cómo cada uno afecta específicamente la madurez de azúcar y fenólica de la uva.","DEVELOPING_RESPONSE":"Buena identificación parcial. Mencionas un mecanismo, pero conecta explícitamente cómo afecta la composición de la uva.","FOUNDATIONAL_RESPONSE":"Mencionas el manejo del dosel pero no identificas mecanismos específicos ni cómo afectan la composición de la uva."}'::jsonb where item_id = 'OR_055';
update public.or_bank set expected_concepts = '["polimerización de los taninos","formación de color teja","desarrollo de aromas secundarios","cambio de fruta hacia notas terrosas","integración de la textura","punto máximo de complejidad aromática"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: describe la evolución química (polimerización, color) y sensorial (aroma, textura) en conjunto, situando el vino en su punto de máxima complejidad.","DEVELOPING_RESPONSE":"Buena descripción parcial. Mencionas el cambio de color o aroma, pero conecta ambos con los cambios químicos subyacentes.","FOUNDATIONAL_RESPONSE":"Mencionas que el vino cambia con el tiempo, pero no describes los cambios químicos (taninos, color) que lo explican."}'::jsonb where item_id = 'OR_056';
update public.or_bank set expected_concepts = '["estructura y microporosidad del corcho","tasa de transmisión de oxígeno","beneficios de la oxidación lenta","polimerización de taninos","desarrollo de color teja","integración aromática"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: describe cómo la microporosidad del corcho regula la entrada de oxígeno, y conecta esa oxidación lenta con la polimerización de taninos y el desarrollo de color y aroma.","DEVELOPING_RESPONSE":"Buena descripción parcial. Mencionas que el corcho permite oxígeno, pero conecta esto con los cambios específicos (taninos, color) que produce.","FOUNDATIONAL_RESPONSE":"Mencionas el corcho pero no explicas cómo su porosidad permite la oxidación lenta ni qué cambios produce en el vino."}'::jsonb where item_id = 'OR_057';
update public.or_bank set expected_concepts = '["efecto de la temperatura en la maduración","tasa de acumulación de azúcar","retención de ácido málico","variación de la madurez fenólica","expresión del carácter de la añada"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Respuesta completa: explica cómo la temperatura acelera la acumulación de azúcar y degrada el ácido málico, y conecta esto con la variación de madurez fenólica entre añadas.","DEVELOPING_RESPONSE":"Buen fundamento. Mencionas que la añada cálida da más alcohol, pero explica el mecanismo: mayor temperatura → más azúcar y menos ácido málico retenido.","FOUNDATIONAL_RESPONSE":"Mencionas que hay diferencia entre añadas, pero no explicas por qué el calor produce mayor alcohol y menor acidez."}'::jsonb where item_id = 'OR_058';
update public.or_bank set expected_concepts = '["el Chardonnay se beneficia de la textura de la fermentación maloláctica","el Sauvignon Blanc se beneficia de preservar su acidez","papel de la acidez en el estilo","complejidad aromática frente a frescura","intención del productor y posicionamiento de mercado"]'::jsonb, feedback_profile = '{"STRONG_RESPONSE":"Comparación completa: contrasta cómo cada varietal se beneficia de forma distinta (textura vs. frescura) y conecta esto con la intención estilística del productor.","DEVELOPING_RESPONSE":"Buen contraste inicial. Mencionas una diferencia varietal, pero explica por qué cada productor elige distinto según el estilo que busca.","FOUNDATIONAL_RESPONSE":"Mencionas que la fermentación maloláctica se usa distinto en cada varietal, pero no explicas por qué (textura en Chardonnay vs. frescura en Sauvignon Blanc)."}'::jsonb where item_id = 'OR_059';
